// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DocumentRegistry
 * @dev Contrato principal para registro de documentos en blockchain
 * 
 * Nota: ipfsCid y encryptedKey se almacenan en DocumentVersioning,
 * este contrato solo mantiene metadatos esenciales del documento.
 */
contract DocumentRegistry is Ownable, ReentrancyGuard {
    struct Document {
        address owner;
        bytes32 docId;              // Hash único del documento
        uint256 currentVersion;     // Versión operacional actual
        uint256 latestVersion;      // Última versión creada
        bool isArchived;
        bool isDeleted;
        uint256 createdAt;
        uint256 updatedAt;
    }

    mapping(bytes32 => Document) public documents;
    mapping(address => bytes32[]) public userDocuments;

    event DocumentCreated(
        bytes32 indexed docId,
        address indexed owner,
        uint256 timestamp
    );

    event DocumentShared(
        bytes32 indexed docId,
        address indexed from,
        address indexed to,
        uint256 timestamp
    );

    event DocumentArchived(
        bytes32 indexed docId,
        address indexed by,
        uint256 timestamp
    );

    event DocumentUnarchived(
        bytes32 indexed docId,
        address indexed by,
        uint256 timestamp
    );

    event DocumentDeleted(
        bytes32 indexed docId,
        address indexed by,
        uint256 timestamp
    );

    event DocumentTransferred(
        bytes32 indexed docId,
        address indexed from,
        address indexed to,
        uint256 timestamp
    );

    event DocumentVersionUpdated(
        bytes32 indexed docId,
        uint256 newVersion,
        address indexed by,
        uint256 timestamp
    );

    constructor() Ownable(msg.sender) {}

    /**
     * @dev Crear un nuevo documento (solo metadatos, versiones en DocumentVersioning)
     */
    function createDocument(bytes32 _docId) external nonReentrant {
        require(documents[_docId].owner == address(0), "El documento ya existe");
        require(_docId != bytes32(0), "Id de documento invalido");

        documents[_docId] = Document({
            owner: msg.sender,
            docId: _docId,
            currentVersion: 1,
            latestVersion: 1,
            isArchived: false,
            isDeleted: false,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        userDocuments[msg.sender].push(_docId);

        emit DocumentCreated(_docId, msg.sender, block.timestamp);
    }

    /**
     * @dev Compartir documento (solo registra el evento)
     */
    function shareDocument(
        bytes32 _docId,
        address _to
    ) external nonReentrant {
        Document storage doc = documents[_docId];
        require(doc.owner == msg.sender, "No es el propietario");
        require(!doc.isDeleted, "Documento eliminado");
        require(_to != address(0), "Direccion invalida");
        require(_to != msg.sender, "No puede compartir consigo mismo");

        emit DocumentShared(_docId, msg.sender, _to, block.timestamp);
    }

    /**
     * @dev Archivar documento
     */
    function archiveDocument(bytes32 _docId) external nonReentrant {
        Document storage doc = documents[_docId];
        require(doc.owner == msg.sender, "No es el propietario");
        require(!doc.isArchived, "Ya esta archivado");
        require(!doc.isDeleted, "Documento eliminado");

        doc.isArchived = true;
        doc.updatedAt = block.timestamp;

        emit DocumentArchived(_docId, msg.sender, block.timestamp);
    }

    /**
     * @dev Desarchivar documento
     */
    function unarchiveDocument(bytes32 _docId) external nonReentrant {
        Document storage doc = documents[_docId];
        require(doc.owner == msg.sender, "No es el propietario");
        require(doc.isArchived, "No esta archivado");
        require(!doc.isDeleted, "Documento eliminado");

        doc.isArchived = false;
        doc.updatedAt = block.timestamp;

        emit DocumentUnarchived(_docId, msg.sender, block.timestamp);
    }

    /**
     * @dev Eliminar documento (soft delete)
     */
    function deleteDocument(bytes32 _docId) external nonReentrant {
        Document storage doc = documents[_docId];
        require(doc.owner == msg.sender, "No es el propietario");
        require(!doc.isDeleted, "Ya esta eliminado");

        doc.isDeleted = true;
        doc.updatedAt = block.timestamp;

        emit DocumentDeleted(_docId, msg.sender, block.timestamp);
    }

    /**
     * @dev Transferir documento completo (todas las versiones)
     */
    function transferDocument(
        bytes32 _docId,
        address _to
    ) external nonReentrant {
        Document storage doc = documents[_docId];

        require(doc.owner == msg.sender, "No es el propietario");
        require(!doc.isArchived, "No se puede transferir documento archivado");
        require(!doc.isDeleted, "No se puede transferir documento eliminado");
        require(_to != address(0), "Direccion invalida");
        require(_to != msg.sender, "No se puede transferir a si mismo");

        address previousOwner = doc.owner;

        doc.owner = _to;
        doc.updatedAt = block.timestamp;

        _moveDocumentBetweenUsers(_docId, previousOwner, _to);

        emit DocumentTransferred(_docId, previousOwner, _to, block.timestamp);
    }

    /**
     * @dev Actualizar versión del documento (llamado por DocumentVersioning)
     */
    function updateVersion(bytes32 _docId, uint256 _newVersion) external {
        Document storage doc = documents[_docId];
        require(doc.owner == msg.sender, "No es el propietario");
        require(!doc.isDeleted, "Documento eliminado");
        require(_newVersion > doc.latestVersion, "La version debe ser mayor");

        doc.latestVersion = _newVersion;
        doc.currentVersion = _newVersion;
        doc.updatedAt = block.timestamp;

        emit DocumentVersionUpdated(_docId, _newVersion, msg.sender, block.timestamp);
    }

    /**
     * @dev Actualizar versión operacional (llamado cuando se cambia la versión activa)
     */
    function setOperationalVersion(bytes32 _docId, uint256 _versionNumber) external {
        Document storage doc = documents[_docId];
        require(doc.owner == msg.sender, "No es el propietario");
        require(!doc.isDeleted, "Documento eliminado");
        require(_versionNumber <= doc.latestVersion, "Version no existe");

        doc.currentVersion = _versionNumber;
        doc.updatedAt = block.timestamp;
    }

    /**
     * @dev Obtener documentos de un usuario
     */
    function getUserDocuments(address _user) external view returns (bytes32[] memory) {
        return userDocuments[_user];
    }

    /**
     * @dev Obtener documento
     */
    function getDocument(bytes32 _docId) external view returns (Document memory) {
        return documents[_docId];
    }

    /**
     * @dev Verificar si es dueño
     */
    function isOwner(bytes32 _docId, address _user) external view returns (bool) {
        return documents[_docId].owner == _user;
    }

    /**
     * @dev Mover documento entre usuarios (internal)
     */
    function _moveDocumentBetweenUsers(
        bytes32 _docId,
        address _from,
        address _to
    ) internal {
        // Remover de la lista del anterior dueño
        bytes32[] storage fromDocs = userDocuments[_from];
        for (uint i = 0; i < fromDocs.length; i++) {
            if (fromDocs[i] == _docId) {
                fromDocs[i] = fromDocs[fromDocs.length - 1];
                fromDocs.pop();
                break;
            }
        }

        // Agregar a la lista del nuevo dueño
        userDocuments[_to].push(_docId);
    }
}

