// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title DocumentSigning
 * @dev Gestión de firmas digitales de documentos
 */
contract DocumentSigning {
    struct Signature {
        bytes32 docId;
        uint256 versionNumber;
        address signer;
        bytes signature;
        string message;         // Mensaje firmado
        string comment;         // Comentario breve sobre la firma
        uint256 timestamp;
    }

    // Mapping: docId → version → signatures
    mapping(bytes32 => mapping(uint256 => Signature[])) public versionSignatures;
    mapping(bytes32 => mapping(uint256 => mapping(address => bool))) public hasSignedVersion;

    event DocumentVersionSigned(
        bytes32 indexed docId,
        uint256 indexed versionNumber,
        address indexed signer,
        string message,
        string comment,
        uint256 timestamp
    );

    /**
     * @dev Firmar una versión específica de un documento
     */
    function signDocumentVersion(
        bytes32 _docId,
        uint256 _versionNumber,
        bytes calldata _signature,
        string calldata _message,
        string calldata _comment
    ) external {
        require(_docId != bytes32(0), "Id de documento invalido");
        require(_versionNumber > 0, "Numero de version invalido");
        require(_signature.length > 0, "Firma invalida");
        require(bytes(_message).length > 0, "Mensaje invalido");

        // Verificar que no haya firmado esta versión antes
        require(
            !hasSignedVersion[_docId][_versionNumber][msg.sender],
            "Ya ha firmado esta version"
        );

        // Registrar la firma
        versionSignatures[_docId][_versionNumber].push(Signature({
            docId: _docId,
            versionNumber: _versionNumber,
            signer: msg.sender,
            signature: _signature,
            message: _message,
            comment: _comment,
            timestamp: block.timestamp
        }));

        hasSignedVersion[_docId][_versionNumber][msg.sender] = true;

        emit DocumentVersionSigned(_docId, _versionNumber, msg.sender, _message, _comment, block.timestamp);
    }

    /**
     * @dev Obtener firmas de una versión específica
     */
    function getVersionSignatures(
        bytes32 _docId,
        uint256 _versionNumber
    ) external view returns (Signature[] memory) {
        return versionSignatures[_docId][_versionNumber];
    }

    /**
     * @dev Obtener número de firmas de una versión
     */
    function getVersionSignatureCount(
        bytes32 _docId,
        uint256 _versionNumber
    ) external view returns (uint256) {
        return versionSignatures[_docId][_versionNumber].length;
    }

    /**
     * @dev Verificar si un usuario ha firmado una versión
     */
    function hasUserSignedVersion(
        bytes32 _docId,
        uint256 _versionNumber,
        address _user
    ) external view returns (bool) {
        return hasSignedVersion[_docId][_versionNumber][_user];
    }

    /**
     * @dev Obtener todas las versiones con firmas (limitado a 100 versiones)
     */
    function getAllDocumentSignatures(
        bytes32 _docId
    ) external view returns (
        uint256[] memory versions,
        uint256[] memory signatureCounts
    ) {
        uint256 count = 0;

        // Contar versiones con firmas
        for (uint256 i = 1; i <= 100; i++) {
            if (versionSignatures[_docId][i].length > 0) {
                count++;
            }
        }

        versions = new uint256[](count);
        signatureCounts = new uint256[](count);

        uint256 index = 0;
        for (uint256 i = 1; i <= 100; i++) {
            if (versionSignatures[_docId][i].length > 0) {
                versions[index] = i;
                signatureCounts[index] = versionSignatures[_docId][i].length;
                index++;
            }
        }

        return (versions, signatureCounts);
    }
}

contracts/DocumentVersioning.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DocumentVersioning
 * @dev Gestión de versiones de documentos
 * 
 * Campos importantes:
 * - isOperational: Indica la versión activa del documento (solo UNA puede ser operacional)
 * - restoredFrom: Si > 0, indica que esta versión fue creada restaurando una versión anterior
 */
contract DocumentVersioning is ReentrancyGuard, Ownable {
    struct Version {
        bytes32 docId;
        uint256 versionNumber;
        string ipfsCid;
        address createdBy;
        uint256 createdAt;
        bool isOperational;       // Solo una versión puede ser operativa
        uint256 restoredFrom;     // Si fue restaurada (0 = no restaurada)
    }

    mapping(bytes32 => Version[]) public documentVersions;
    mapping(bytes32 => uint256) public latestVersion;
    mapping(bytes32 => uint256) public operationalVersion;

    // Referencia al contrato de control de acceso
    address public accessControlAddress;

    event VersionCreated(
        bytes32 indexed docId,
        uint256 versionNumber,
        string ipfsCid,
        address indexed createdBy,
        uint256 timestamp
    );

    event VersionRestored(
        bytes32 indexed docId,
        uint256 newVersionNumber,
        uint256 restoredFromVersion,
        string ipfsCid,
        address indexed by,
        uint256 timestamp
    );

    event VersionSetOperational(
        bytes32 indexed docId,
        uint256 versionNumber,
        address indexed by,
        uint256 timestamp
    );

    constructor() Ownable(msg.sender) {}

    /**
     * @dev Establecer dirección del contrato de control de acceso
     */
    function setAccessControl(address _accessControl) external onlyOwner {
        accessControlAddress = _accessControl;
    }

    /**
     * @dev Inicializar documento con primera versión
     */
    function initializeDocument(
        bytes32 _docId,
        string calldata _ipfsCid
    ) external {
        require(latestVersion[_docId] == 0, "Documento ya inicializado");
        require(bytes(_ipfsCid).length > 0, "CID de IPFS invalido");

        documentVersions[_docId].push(Version({
            docId: _docId,
            versionNumber: 1,
            ipfsCid: _ipfsCid,
            createdBy: msg.sender,
            createdAt: block.timestamp,
            isOperational: true,
            restoredFrom: 0
        }));

        latestVersion[_docId] = 1;
        operationalVersion[_docId] = 1;

        emit VersionCreated(_docId, 1, _ipfsCid, msg.sender, block.timestamp);
        emit VersionSetOperational(_docId, 1, msg.sender, block.timestamp);
    }

    /**
     * @dev Crear nueva versión
     */
    function createVersion(
        bytes32 _docId,
        string calldata _ipfsCid
    ) external nonReentrant {
        require(operationalVersion[_docId] > 0, "Documento no inicializado");
        require(latestVersion[_docId] > 0, "Documento no encontrado");
        require(bytes(_ipfsCid).length > 0, "CID de IPFS invalido");

        uint256 newVersionNumber = latestVersion[_docId] + 1;

        documentVersions[_docId].push(Version({
            docId: _docId,
            versionNumber: newVersionNumber,
            ipfsCid: _ipfsCid,
            createdBy: msg.sender,
            createdAt: block.timestamp,
            isOperational: true,
            restoredFrom: 0
        }));

        // Marcar la anterior como no operativa
        _setNonOperational(_docId, operationalVersion[_docId]);

        latestVersion[_docId] = newVersionNumber;
        operationalVersion[_docId] = newVersionNumber;

        emit VersionCreated(_docId, newVersionNumber, _ipfsCid, msg.sender, block.timestamp);
        emit VersionSetOperational(_docId, newVersionNumber, msg.sender, block.timestamp);
    }

    /**
     * @dev Restaurar versión anterior (crea nueva versión con contenido de la anterior)
     */
    function restoreVersion(
        bytes32 _docId,
        uint256 _versionToRestore
    ) external nonReentrant {
        require(operationalVersion[_docId] > 0, "Documento no inicializado");
        require(_versionToRestore <= latestVersion[_docId], "Version invalida");
        require(_versionToRestore > 0, "Version invalida");

        // Buscar la versión a restaurar
        string memory ipfsCid;
        bool found = false;

        for (uint i = 0; i < documentVersions[_docId].length; i++) {
            if (documentVersions[_docId][i].versionNumber == _versionToRestore) {
                ipfsCid = documentVersions[_docId][i].ipfsCid;
                found = true;
                break;
            }
        }

        require(found, "Version no encontrada");
        require(bytes(ipfsCid).length > 0, "CID de IPFS invalido");

        uint256 newVersionNumber = latestVersion[_docId] + 1;

        documentVersions[_docId].push(Version({
            docId: _docId,
            versionNumber: newVersionNumber,
            ipfsCid: ipfsCid,  // Usar el CID de la versión restaurada
            createdBy: msg.sender,
            createdAt: block.timestamp,
            isOperational: true,
            restoredFrom: _versionToRestore
        }));

        // Marcar la anterior como no operativa
        _setNonOperational(_docId, operationalVersion[_docId]);

        latestVersion[_docId] = newVersionNumber;
        operationalVersion[_docId] = newVersionNumber;

        emit VersionRestored(_docId, newVersionNumber, _versionToRestore, ipfsCid, msg.sender, block.timestamp);
        emit VersionSetOperational(_docId, newVersionNumber, msg.sender, block.timestamp);
    }

    /**
     * @dev Cambiar la versión operacional (activa) del documento
     * @param _docId ID del documento
     * @param _versionNumber Número de versión a establecer como operacional
     */
    function setOperationalVersion(
        bytes32 _docId,
        uint256 _versionNumber
    ) external nonReentrant {
        require(_versionNumber > 0, "Version invalida");
        require(_versionNumber <= latestVersion[_docId], "Version no existe");
        require(_versionNumber != operationalVersion[_docId], "Ya es la version operacional");

        // Verificar ownership via access control si está configurado
        if (accessControlAddress != address(0)) {
            // Interface simplificada para verificar ownership
            (bool success, bytes memory data) = accessControlAddress.staticcall(
                abi.encodeWithSignature("isOwner(bytes32,address)", _docId, msg.sender)
            );
            require(success && abi.decode(data, (bool)), "No es el propietario");
        }

        // Desmarcar versión operacional anterior
        _setNonOperational(_docId, operationalVersion[_docId]);

        // Marcar nueva versión operacional
        _setOperational(_docId, _versionNumber);
        operationalVersion[_docId] = _versionNumber;

        emit VersionSetOperational(_docId, _versionNumber, msg.sender, block.timestamp);
    }

    /**
     * @dev Obtener todas las versiones de un documento
     */
    function getVersions(bytes32 _docId) external view returns (Version[] memory) {
        return documentVersions[_docId];
    }

    /**
     * @dev Obtener versión operativa
     */
    function getOperationalVersion(bytes32 _docId) external view returns (Version memory) {
        uint256 opVer = operationalVersion[_docId];
        require(opVer > 0, "No hay version operativa");

        for (uint i = 0; i < documentVersions[_docId].length; i++) {
            if (documentVersions[_docId][i].versionNumber == opVer) {
                return documentVersions[_docId][i];
            }
        }

        revert("Version operativa no encontrada");
    }

    /**
     * @dev Obtener versión específica
     */
    function getVersion(bytes32 _docId, uint256 _versionNumber) external view returns (Version memory) {
        for (uint i = 0; i < documentVersions[_docId].length; i++) {
            if (documentVersions[_docId][i].versionNumber == _versionNumber) {
                return documentVersions[_docId][i];
            }
        }

        revert("Version no encontrada");
    }

    /**
     * @dev Obtener número de versión operativa
     */
    function getOperationalVersionNumber(bytes32 _docId) external view returns (uint256) {
        return operationalVersion[_docId];
    }

    /**
     * @dev Obtener número de última versión
     */
    function getLatestVersionNumber(bytes32 _docId) external view returns (uint256) {
        return latestVersion[_docId];
    }

    /**
     * @dev Marcar versión como no operativa (internal)
     */
    function _setNonOperational(bytes32 _docId, uint256 _versionNumber) internal {
        for (uint i = 0; i < documentVersions[_docId].length; i++) {
            if (documentVersions[_docId][i].versionNumber == _versionNumber) {
                documentVersions[_docId][i].isOperational = false;
                break;
            }
        }
    }

    /**
     * @dev Marcar versión como operativa (internal)
     */
    function _setOperational(bytes32 _docId, uint256 _versionNumber) internal {
        for (uint i = 0; i < documentVersions[_docId].length; i++) {
            if (documentVersions[_docId][i].versionNumber == _versionNumber) {
                documentVersions[_docId][i].isOperational = true;
                break;
            }
        }
    }
}

